#include <stdint.h>
#include <stdio.h>

/* Provided by the candidate in solution.c */
int32_t can_mux_decode(const uint8_t *frame, int32_t length,
                       int32_t *out_a, int32_t *out_b);

int main(void)
{
    int length;
    while (scanf("%d", &length) == 1) {
        uint8_t frame[16];
        for (int i = 0; i < length; i++) {
            unsigned int byte_value;
            if (scanf("%x", &byte_value) != 1) {
                return 1;
            }
            frame[i] = (uint8_t)byte_value;
        }

        int32_t out_a = 0, out_b = 0;
        int32_t kind = can_mux_decode(frame, (int32_t)length, &out_a, &out_b);
        if (kind == 0) {
            printf("A %d %d\n", out_a, out_b);
        } else if (kind == 1) {
            printf("B %d %d\n", out_a, out_b);
        } else {
            printf("REJECT\n");
        }
    }
    return 0;
}

