"""Random frames across both multiplexor values, plus unrecognised
multiplexors and frames too short for the one they select."""


def generate(rng, count):
    builders = (_mux0_frame, _mux1_frame, _unknown_mux, _too_short)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, frame, description=""):
    hexed = " ".join("%02X" % b for b in frame)
    return {"name": name, "stdin": "%d\n%s\n" % (len(frame), hexed),
            "description": description}


def _mux0_frame(rng, index):
    high_nibble = rng.randrange(16) << 4
    byte0 = high_nibble | 0
    raw16 = rng.randrange(0, 65536)
    raw12 = rng.randrange(0, 4096)
    pad = rng.randrange(16) << 12
    word = raw12 | pad
    frame = [
        byte0,
        raw16 & 0xFF, (raw16 >> 8) & 0xFF,
        word & 0xFF, (word >> 8) & 0xFF,
    ]
    return _case("a random mux-0 frame #%d" % index, frame)


def _mux1_frame(rng, index):
    high_nibble = rng.randrange(16) << 4
    byte0 = high_nibble | 1
    raw8 = rng.randrange(0, 256)
    flag_byte = rng.randrange(0, 256)
    frame = [byte0, raw8, flag_byte]
    return _case("a random mux-1 frame #%d" % index, frame)


def _unknown_mux(rng, index):
    mux = rng.randrange(2, 16)
    high_nibble = rng.randrange(16) << 4
    byte0 = high_nibble | mux
    length = rng.randrange(1, 9)
    frame = [byte0] + [rng.randrange(256) for _ in range(length - 1)]
    return _case("an unrecognised multiplexor value %d #%d" % (mux, index),
                 frame)


def _too_short(rng, index):
    which = rng.choice((0, 1))
    if which == 0:
        length = rng.randrange(1, 5)
        byte0 = (rng.randrange(16) << 4) | 0
    else:
        length = rng.randrange(1, 3)
        byte0 = (rng.randrange(16) << 4) | 1
    frame = [byte0] + [rng.randrange(256) for _ in range(length - 1)]
    return _case("a frame too short for mux %d #%d" % (which, index), frame)
